   "id": "z164749c9",
   "sez": "prima",
   "titolo": "Attacco informatico sospetto blocca i congelatori dei supermercati in Belgio e Svezia",
   "orig": "Supermarket freezers in Belgium and Sweden hit by suspected cyber-attack",
   "lead": "In diversi supermercati di Svezia, Belgio e Lussemburgo le temperature di frigoriferi e congelatori sono salite improvvisamente durante la notte, in un episodio simile a quello che aveva colpito i negozi francesi lo scorso ottobre. Un punto vendita svedese ha riferito che i congelatori erano stati impostati a 50°C. Le catene sospettano un attacco informatico, ma non è ancora chiaro chi lo abbia condotto né quali danni abbia causato alla merce deperibile. L'episodio arriva poche settimane dopo il primo caso in Francia e alimenta i timori su vulnerabilità informatiche nei sistemi di refrigerazione dei supermercati europei.",
   "more": [
    "I sistemi di controllo industriale, come quelli che regolano temperatura e refrigerazione, sono sempre più collegati a reti informatiche per ragioni di efficienza, ma questo li rende vulnerabili ad attacchi esterni. Un attacco riuscito può causare danni economici tramite la perdita di merce deperibile e mettere in discussione la sicurezza delle infrastrutture critiche della filiera alimentare."
   ],
