   "id": "z82611c57",
   "sez": "prima",
   "titolo": "L'autore australiano Craig Silvey condannato al carcere per materiale di abuso su minori",
   "orig": "Popular Australian children's author jailed over child exploitation offences",
   "lead": "Lo scrittore australiano Craig Silvey, autore dei romanzi \"Jasper Jones\" e \"Runt\", è stato condannato al carcere per reati legati a materiale di abuso sessuale su minori. Silvey si era dichiarato colpevole lo scorso maggio, dopo che la polizia aveva perquisito la sua abitazione mesi prima. Il tribunale distrettuale dell'Australia Occidentale ha sentito che l'autore aveva inviato numerosi messaggi in cui esprimeva desiderio sessuale verso ragazzi giovani.",
   "more": [
    "Craig Silvey è un autore noto soprattutto per il romanzo per giovani adulti \"Jasper Jones\", pubblicato nel 2009 e diventato un successo in Australia, poi adattato anche al cinema. I casi di adulti con ruoli pubblici accusati di materiale di abuso su minori comportano spesso perquisizioni informatiche che portano al ritrovamento di comunicazioni compromettenti."
   ],
