   "id": "zdab07809",
   "sez": "sport",
   "titolo": "Negli Usa parte il processo per presunto spot-fixing nel baseball",
   "orig": "MLB ‘spot-fixing’ trial set to begin in US court",
   "lead": "Negli Stati Uniti si apre un processo per presunto \"spot-fixing\" nel baseball: alcuni lanciatori della Major League Baseball sono accusati di cospirazione per aver influenzato l'esito di gare sportive tramite corruzione. Il processo si svolge in un tribunale di New York. Lo riferisce Al Jazeera.",
   "more": [
    "Lo spot-fixing è una forma di manipolazione sportiva in cui vengono alterati episodi specifici di una partita, come un lancio o un'azione, piuttosto che il risultato finale, spesso legata al mercato delle scommesse sportive."
   ],
