   "id": "z0734fb93",
   "sez": "economia",
   "titolo": "Bangladesh, proseguono le proteste degli operai del settore abbigliamento",
   "orig": "Bangladesh garment factories disrupted as protests continue for third day",
   "lead": "In Bangladesh le proteste dei lavoratori dell'industria dell'abbigliamento, il principale settore di esportazione del paese, continuano per il terzo giorno consecutivo. I manifestanti chiedono un aumento del salario minimo mensile più del doppio rispetto a quello attuale, in un contesto di inflazione crescente. Lunedì migliaia di operai hanno bloccato una delle principali autostrade e si sono scontrati con la polizia. Oltre 150 fabbriche sono state chiuse nel distretto di Gazipur a causa delle proteste.",
   "more": [
    "Il Bangladesh è uno dei maggiori produttori mondiali di abbigliamento, un settore che occupa milioni di lavoratori spesso con salari bassi rispetto al costo della vita. Le proteste per l'aumento del salario minimo sono ricorrenti nel paese e talvolta sfociano in scontri con le forze dell'ordine."
   ],
