   "sez": "ingegneria",
   "titolo": "Molti studi di architettura a Londra non pagano il London Living Wage",
   "orig": "Many London architecture firms not paying London Living Wage",
   "lead": "Secondo l'ultimo sondaggio annuale sulle retribuzioni \"The Pay 100\", la maggioranza degli studi di architettura con sede a Londra non paga ai propri assistenti architettonici di primo livello il London Living Wage, il salario minimo di riferimento per la città. Si tratta della quinta edizione dell'indagine condotta sul settore. Lo riferisce Dezeen.",
   "more": [
    "Il London Living Wage è un salario minimo calcolato sul costo della vita nella capitale britannica, superiore al salario minimo nazionale, promosso da organizzazioni indipendenti ma non obbligatorio per legge, sulla cui adozione le aziende decidono volontariamente."
   ],
