   "id": "z65baaa31",
   "sez": "dibattito",
   "titolo": "Repubblica Ceca, sciopero riduce i programmi della Radio Ceca mentre si discute il canone",
   "orig": "Czech Radio to scale back news and current affairs during Tuesday strike",
   "lead": "Martedì la Radio Ceca ridurrà i programmi di informazione e attualità a causa di uno sciopero. In Repubblica Ceca è in corso un dibattito sul finanziamento dei media pubblici: secondo il governo, tramite il ministero delle Finanze, si sta preparando un nuovo modello che permetterebbe ai cittadini di scegliere volontariamente se pagare il canone per televisione e radio pubbliche, come ha annunciato il primo ministro Andrej Babiš. Le fonti non specificano se lo sciopero sia legato direttamente a questa proposta né quale sia la posizione dei sindacati o del personale in merito.",
   "more": [
    "In molti paesi europei le emittenti pubbliche sono finanziate tramite un canone obbligatorio pagato dai cittadini, pensato per garantirne l'indipendenza economica dal mercato pubblicitario e dalle pressioni politiche. Rendere il pagamento volontario, come proposto in Repubblica Ceca, potrebbe ridurre le entrate disponibili e influire sulla sostenibilità finanziaria del servizio pubblico radiotelevisivo."
   ],
