   "titolo": "Praga ospita una settimana di cinema e cultura polacca",
   "orig": "Prague Welcomes a Week of Polish Films and Culture",
   "lead": "Praga ospiterà dal 9 al 15 novembre una settimana dedicata al cinema e alla cultura polacca, nell'ambito della tredicesima edizione del \"3Kino – Polish Film Festival Prague\". Il programma prevede la proiezione di 13 lungometraggi del cinema polacco contemporaneo, oltre a teatro, stand-up comedy, mostre, musica ed eventi per bambini. Il festival si apre con \"La bambola\" (Lalka), diretto da Maciej Kawalski e basato sul classico romanzo di Bolesław Prus, tra i film polacchi più costosi mai realizzati. Lo riferisce Prague Morning.",
