   "id": "zfbf92d90",
   "sez": "mondo",
   "titolo": "Drone ucraini colpiscono nella notte la regione russa di Samara, forse il più grande deposito petrolifero d'Europa",
   "orig": "Ukrainian drones attack Russia’s Samara region, reportedly striking Europe’s largest oil storage facility",
   "lead": "Droni ucraini hanno attaccato nella notte tra il 1° e il 2 novembre la regione russa di Samara, colpendo secondo diverse fonti un impianto legato al trasporto di petrolio di proprietà della società Transneft. L'aeroporto di Samara ha sospeso le operazioni per due ore a causa della minaccia dei drone. Le autorità regionali russe non avevano ancora commentato ufficialmente gli attacchi al momento della pubblicazione delle notizie. L'impianto sarebbe già stato colpito più volte nel corso del mese. Lo riferiscono Meduza, Moscow Times e The Kyiv Independent.",
   "more": [
    "La regione di Samara, a centinaia di chilometri dal confine ucraino, ospita importanti infrastrutture petrolifere russe. Da mesi l'Ucraina colpisce con drone a lungo raggio raffinerie e depositi di carburante in territorio russo, nel tentativo di danneggiare l'industria energetica che finanzia lo sforzo bellico di Mosca."
   ],
