   "lead": "La polizia ceca ha dichiarato giustificato il proprio intervento contro un gruppo di manifestanti che si erano introdotti nella Camera bassa del Parlamento a Praga. Le forze dell'ordine sostengono di aver agito secondo le procedure previste per garantire la sicurezza dell'edificio istituzionale. Le fonti non specificano le richieste dei manifestanti né le motivazioni della protesta. Lo riferisce Radio Prague International.",
