   "titolo": "Strictly Come Dancing, chi ha lasciato la pista dopo il primo triplo spareggio della storia del programma",
   "orig": "Halloween Week: Who left the Strictly dance floor?",
   "lead": "Il programma televisivo britannico Strictly Come Dancing ha visto per la prima volta nei suoi 22 anni di storia uno spareggio a tre coppie durante la settimana di Halloween. Il verdetto finale ha stabilito quale coppia è stata eliminata dalla competizione dopo questo inedito confronto diretto. Lo riferisce BBC Newsround.",
