   "titolo": "Un americano vede 1.207 film in un anno e stabilisce un record Guinness",
   "orig": "US man watches 1,207 movies in a year, sets Guinness World Record",
   "lead": "Glenwood Hoskin Jr., 60 anni, della Pennsylvania, ha stabilito un nuovo record mondiale guardando 1.207 film in un anno, con una media di 3,3 pellicole al giorno, superando il precedente primato per la frequentazione cinematografica. L'uomo ha spiegato di aver pianificato meticolosamente gli orari delle proiezioni e di aver controllato le spese grazie a un abbonamento. Appassionato soprattutto di animazione e commedie, ha detto di apprezzare particolarmente le risate del pubblico durante le commedie. Lo riferisce Times of India.",
