   "lead": "Il ministro degli Esteri iraniano Seyyed Abbas Araghchi guida questa settimana una delegazione diplomatica ed economica in visita in Turkmenistan, con l'obiettivo di rafforzare le relazioni bilaterali tra i due Paesi. La visita rientra in un contesto di intensificazione dei rapporti economici tra Teheran e Ashgabat. Lo riferisce The Times of Central Asia.",
