   "titolo": "Meloni toglie a Vannacci il tema sicurezza, ma gli equilibri politici restano invariati",
   "orig": "Così Meloni ha sfilato il tema sicurezza a Vannacci, ma non ha ribaltato gli equilibri",
   "lead": "Secondo un'analisi pubblicata in Italia, la premier Giorgia Meloni sarebbe riuscita a sottrarre al generale Roberto Vannacci il tema della sicurezza, tradizionalmente cavallo di battaglia della destra più identitaria. Tuttavia, secondo la stessa analisi, vincere la battaglia dell'agenda politica non equivale necessariamente a vincere quella elettorale, poiché gli equilibri tra le forze di governo non sarebbero stati ribaltati. Lo riferisce la Repubblica.",
