   "orig": "FDC Questions Power Exports as Rural Electricity Access Remains Low",
   "lead": "In Uganda il partito di opposizione FDC ha criticato le esportazioni di energia elettrica verso i Paesi vicini, sostenendo che il governo dovrebbe prima garantire l'accesso all'elettricità alle comunità rurali ancora poco servite. Secondo il partito, la priorità dovrebbe essere collegare le zone sottoservite prima di ampliare le esportazioni. Lo riferisce Nile Post.",
