    "Molti Paesi dell'Africa orientale producono energia idroelettrica in eccedenza rispetto al proprio fabbisogno interno e la esportano ai vicini, mentre ampie zone rurali restano senza collegamento alla rete elettrica. Il tema genera spesso dibattiti politici su priorità infrastrutturali e sviluppo locale."
