   "titolo": "In Ghana si chiede alla Commissione minerali di fermare la \"ostilità\" verso le miniere locali",
   "orig": "Minerals Commission must stop the &#39;hawkish hostility&#39; & targeting of indigenous mines - Manteaw",
   "lead": "In Ghana, l'economista Steve Manteaw ha chiesto alla Minerals Commission di interrompere quello che ha definito un atteggiamento ostile verso le compagnie minerarie indigene. Secondo Manteaw non è coerente promuovere l'indigenizzazione del settore e al contempo ostacolare le aziende minerarie nazionali; ha invitato a trovare modi per sostenere le imprese ghanesi. Lo riferisce 3News.",
