   "titolo": "Serbia, arrestato il proprietario di Alta banka mentre la crisi si estende alla Macedonia del Nord",
   "orig": "Nova.rs: Priveden Davor Macura, biznismen blizak SNS-u i vlasnik...",
   "lead": "A Belgrado è stato arrestato Davor Macura, imprenditore vicino al Partito progressista serbo (SNS) e proprietario di Alta banka, dopo più di 30 ore di perquisizioni della polizia negli uffici dell'istituto a partire da sabato. La crisi della banca ha superato i confini della Serbia: la Banca nazionale della Macedonia del Nord ha introdotto un'amministrazione temporanea in Alta banka Bitola per proteggere i beni e i depositanti, dopo i problemi della casa madre serba. Lo riferiscono Vijesti, N1 Serbia e N1 Bosnia.",
