   "id": "z9e785a68",
   "sez": "mondo",
   "titolo": "Marocco, quattro anni di carcere per l'artista Yasser Mounbir che aveva caricaturato il re",
   "orig": "Maroc : l'artiste Yasser Mounbir condamné à quatre ans de prison",
   "lead": "La giustizia marocchina ha condannato a quattro anni di carcere il giovane disegnatore Yasser Mounbir, 22 anni, autore di caricature del re Mohammed VI, per il reato di \"insulto al re\". L'artista, noto per opere di impegno sociale, era stato arrestato nel mese di giugno. Il suo avvocato ha reso noti i dettagli della condanna domenica, annunciando il deposito di un appello. Lo riferiscono France 24 e Seneweb.",
   "more": [
    "In Marocco la legge punisce l'oltraggio alla figura del re, considerata un reato che limita la libertà di espressione artistica e di critica politica. Diverse organizzazioni per i diritti umani hanno più volte denunciato l'uso di questa norma contro artisti, giornalisti e attivisti."
   ],
