   "sez": "mondo",
   "titolo": "Tanzania, i rifugiati burundesi nel campo di Nyarugusu denunciano l'esclusione dall'aiuto umanitario",
   "orig": "Nyarugusu : les réfugiés burundais dénoncent leur exclusion de l’aide humanitaire",
   "lead": "Nel campo di Nyarugusu, nel nord-ovest della Tanzania, i rifugiati burundesi denunciano l'esclusione dei loro giovani dai programmi di aiuto umanitario. La denuncia è stata diffusa dai residenti del campo, che vivono da tempo in condizioni di difficoltà. Lo riferisce SOS Médias Burundi.",
   "more": [
    "Decine di migliaia di rifugiati burundesi vivono da anni nei campi in Tanzania, fuggiti da episodi di violenza politica e instabilità nel loro Paese. L'accesso limitato ai programmi di assistenza internazionale è una criticità ricorrente nei grandi campi rifugiati gestiti da organizzazioni umanitarie con risorse spesso insufficienti."
   ],
