   "sez": "economia",
   "titolo": "Gabon, Marcel Abéké insediato alla guida di Comilog con obiettivo trasformazione locale del manganese",
   "orig": "Comilog : Marcel Abéké installé, cap sur la transformation locale du manganèse",
   "lead": "In Gabon, Marcel Abéké è stato insediato il 30 ottobre alla presidenza del consiglio di amministrazione della Compagnie minière de l'Ogooué (Comilog). Abéké ha fissato nuovi obiettivi al consiglio, dichiarando che sarà giudicato sui risultati e non sulle intenzioni, e ha annunciato un cambiamento di strategia per accelerare la trasformazione locale del manganese prodotto nel Paese. Lo riferisce Gabonreview.",
   "more": [
    "Diversi Paesi africani ricchi di risorse minerarie, come il manganese in Gabon o l'oro in Guinea, stanno cercando di spostare parte della lavorazione delle materie prime all'interno dei propri confini, invece di esportarle grezze, per trattenere maggior valore economico e creare occupazione locale."
   ],
