   "titolo": "Francia, oltre 40 liceo bloccati al rientro dalle vacanze scolastiche",
   "orig": "Mobilisation lycéenne en France : plus de 40 lycées bloqués au retour des vacances scolaires",
   "lead": "In Francia la mobilitazione liceale continua al rientro dalle vacanze: lunedì 2 novembre risultavano bloccati 41 liceo, circa l'1% dei 3.700 istituti del Paese, secondo il ministero dell'Istruzione. Nonostante le concessioni annunciate dal governo la settimana precedente, diverse organizzazioni studentesche hanno deciso di proseguire la protesta. Il premier Sébastien Lecornu si è detto pronto a incontrare nuovamente i rappresentanti liceali \"la prossima settimana\". Alcuni interventi della polizia nei blocchi sono stati definiti a tratti energici. Lo riferiscono France 24, Le Monde, Le Figaro e Libération.",
   "more": [
    "Il movimento di protesta studentesca in Francia è nato da richieste su ristrutturazione degli edifici scolastici, aumento del personale docente e riforma dei criteri di accesso universitario considerati ingiusti. Il governo ha già annunciato alcune concessioni, ma parte del movimento studentesco ritiene le misure insufficienti e continua a chiedere un dialogo diretto con l'esecutivo."
   ],
