   "lead": "In ottobre 2026 l'esercito della Repubblica Democratica del Congo e i gruppi Wazalendo hanno neutralizzato 78 combattenti della ribellione FRN/M23 nei territori di Lubero, Masisi, Walikale e Kalehe. Tra essi 58 si sono arresi volontariamente. Lo riferisce Radio Okapi.",
